  static func registerAll() {
    for name in allThemeNames {
      let tokenMap = tokens(for: name)
      ThemeManager.shared.registerTheme(name: name, tokens: tokenMap)
    }
  }

  static func loadSavedTheme() {
    let saved = UserDefaults.standard.string(forKey: "spec_theme") ?? "default"
    ThemeManager.shared.applyThemeByName(saved)
  }
